  editCode(value:string){this.codeDigits=value.normalize('NFKC').replace(/\D/g,'').slice(0,10);this.codeMessage='';const text=this.overlay?.getByName('settings-code-digits');text?.setText(this.codeDigits||'コードを入力').setColor(this.codeDigits?'#ffffff':'#63787b');this.overlay?.getByName('settings-code-message')?.setText('');}
  rebuildOverlay(){if(this.packetRefreshing)return;super.rebuildOverlay();for(const child of this.overlay?.list??[])if(typeof child.text==='string'&&child.text.includes('絵を押すと1個取得'))child.setText(child.text.replace('絵を押すと1個取得','絵を押して通常・色違いを選択'));for(const icon of [...(this.overlay?.list??[])])if(icon.type==='Image'&&icon.texture?.key?.includes('star_'))for(const [dx,dy]of [[-.3,-.3],[.3,.25],[.1,-.4],[-.35,.2],[.4,-.1],[-.1,.35]]){const spark=this.add.text(icon.x+icon.displayWidth*dx,icon.y+icon.displayHeight*dy,'✦',{fontFamily:'serif',fontSize:'7px',color:'#ffe69a'}).setOrigin(.5);this.overlay.add(spark);this.tweens.add({targets:spark,alpha:.15,scale:.5,duration:700,delay:dx<0?0:350,yoyo:true,repeat:-1});spark.once('destroy',()=>this.tweens.killTweensOf(spark));}if(this.overlayMode==='equip')for(const child of this.overlay?.list??[])if(child.text==='装備・売却')child.setText('装備・ドロップ');}
